// Arasフォームのロード時に第2アコーディオンを展開する処理
function onFormLoad() {
    // アコーディオンのDOM要素を取得（ArasのUI構造に依存）
    var accordions = document.querySelectorAll(".aras-accordion");

    // 第2アコーディオンが存在するか確認
    if (accordions.length >= 2) {
        var secondAccordion = accordions[1];

        // 展開されていない場合は展開する
        if (!secondAccordion.classList.contains("expanded")) {
            secondAccordion.classList.add("expanded");
        }

        // 必要に応じてスクロールやフォーカスも追加可能
        // secondAccordion.scrollIntoView({ behavior: "smooth" });
    }
}
